# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds ui` commands for the Reflex apps. `restart` restarts SmashGPT (the
# experimental/reflex-kernel app, run by the smashgpt.service systemd user service) and waits
# until it answers, eg so it picks up keys just stored with `ds settings sync`.
#
# Example CLI Commands:
#   1. Restart SmashGPT:  ds ui restart
# ---------------------------------------------------------------------------
from __future__ import annotations

import time
import urllib.request
from http import HTTPStatus

import typer
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["ui_app"]


ui_app = typer.Typer(help="SubCommands for reflex ui tool")

TOOLS_DIR = REPO_DIR / "tools" / "smash"

# Same service and URLs as .os/scripts/keybindings/smashgpt.py
SMASHGPT_SERVICE = "smashgpt.service"
SMASHGPT_URLS = ("http://localhost:3000", "http://127.0.0.1:8000/ping")  # page, backend
# A cold `reflex run` (frontend build + dev server) takes about a minute.
SMASHGPT_START_TIMEOUT_S = 150


def _up(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:  # noqa: S310  # fixed localhost URLs
            return response.status < HTTPStatus.INTERNAL_SERVER_ERROR
    except OSError:
        return False


@ui_app.command("run")
def run() -> None:
    """Run reflex ui server"""
    run_cmd(["uv", "run", f"--directory={TOOLS_DIR}", "reflex", "run"])


@ui_app.command("restart")
def restart() -> None:
    """Restart SmashGPT (smashgpt.service) and wait until it answers

    Its server reads stored keys once at start, so run this after `ds settings sync`.
    """
    run_cmd(["systemctl", "--user", "restart", SMASHGPT_SERVICE])
    typer.echo("Waiting for SmashGPT to answer (up to about a minute)...")
    deadline = time.monotonic() + SMASHGPT_START_TIMEOUT_S
    while not all(_up(url) for url in SMASHGPT_URLS):
        if time.monotonic() > deadline:
            typer.echo(f"SmashGPT didn't come up. Logs: journalctl --user -u {SMASHGPT_SERVICE}", err=True)
            raise typer.Exit(1)
        time.sleep(1)
    typer.echo(f"SmashGPT is up: {SMASHGPT_URLS[0]}")
